"""Tests of scripts/python_lockfiles.py, with a PyPI JSON API made here and served from file:// urls."""

import datetime
import io
import json
import sys
import tempfile
import unittest
from contextlib import redirect_stderr, redirect_stdout
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

import python_lockfiles  # noqa: E402  pylint: disable=wrong-import-position

NOW = datetime.datetime.now(datetime.timezone.utc)

LOCKFILE = """#
# This file is autogenerated by pip-compile with Python 3.14
#
--index-url https://pypi.org/simple

Django==6.0.1
    # via -r smarter/requirements/in/base.in
cachecontrol[filecache]==0.15.0
    # via pip-audit
fresh_package==2.0.0 \\
    --hash=sha256:0000000000000000
cache-results==0.2.2
    # via -r smarter/requirements/in/base.in
"""


class TestPythonLockfiles(unittest.TestCase):
    """Test the hashes written into a lockfile, and the cooldown that exempts the project's own packages."""

    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.root = Path(self.tmp.name)
        self.lockfile = self.root / "docker.txt"
        self.lockfile.write_text(LOCKFILE, encoding="utf-8")
        self.pypi = self.root / "pypi"
        self.publish("django", "6.0.1", days_ago=60)
        self.publish("cachecontrol", "0.15.0", days_ago=30)
        # a wheel uploaded three days ago and an sdist today: the release's age is its first file's.
        self.publish("fresh-package", "2.0.0", days_ago=3, later_days_ago=0)
        # the project's own package, uploaded today.
        self.publish("cache-results", "0.2.2", days_ago=0)

    def publish(self, name: str, version: str, days_ago: int, later_days_ago: int | None = None) -> None:
        """
        Write PyPI's JSON for one release: a wheel uploaded days_ago, an sdist later_days_ago, and an egg.

        Each file's sha256 is made from its name, so that the tests can predict it.
        """
        files = []
        wheel_uploaded = NOW - datetime.timedelta(days=days_ago)
        files.append(self.file(name, "bdist_wheel", wheel_uploaded))
        if later_days_ago is not None:
            sdist_uploaded = NOW - datetime.timedelta(days=later_days_ago)
            files.append(self.file(name, "sdist", sdist_uploaded))
        # an egg, which pip doesn't install, and so isn't hashed.
        files.append(self.file(name, "bdist_egg", wheel_uploaded))
        release = self.pypi / name / version
        release.mkdir(parents=True)
        (release / "json").write_text(json.dumps({"urls": files}), encoding="utf-8")

    @staticmethod
    def file(name: str, packagetype: str, uploaded: datetime.datetime) -> dict:
        """One file of a release, in PyPI's JSON."""
        upload_time = uploaded.isoformat().replace("+00:00", "Z")
        sha256 = f"{name}-{packagetype}"
        return {"packagetype": packagetype, "upload_time_iso_8601": upload_time, "digests": {"sha256": sha256}}

    def run_main(self, command: str, *args: str) -> tuple[int, str, str]:
        """Run the script against the test's lockfile and PyPI, and return its exit code and output."""
        out, err = io.StringIO(), io.StringIO()
        argv = [command, str(self.lockfile), "--pypi-url", self.pypi.as_uri(), *args]
        with redirect_stdout(out), redirect_stderr(err):
            code = python_lockfiles.main(argv)
        return code, out.getvalue(), err.getvalue()

    def test_reads_the_pins(self):
        pins = python_lockfiles.read_pins(self.lockfile)
        names = sorted(pin.name for pin in pins)
        self.assertEqual(names, ["cache-results", "cachecontrol", "django", "fresh-package"])
        self.assertIn(python_lockfiles.Pin("cachecontrol", "0.15.0"), pins)

    def test_normalizes_names(self):
        self.assertEqual(python_lockfiles.normalize("Django_Rest.Framework"), "django-rest-framework")

    def test_hash_writes_pip_compiles_format(self):
        code, out, _ = self.run_main("hash")
        self.assertEqual(code, 0)
        self.assertIn("Hashed 4 pins in 1 lockfiles", out)
        text = self.lockfile.read_text(encoding="utf-8")
        expected_django = (
            "Django==6.0.1 \\\n"
            "    --hash=sha256:django-bdist_wheel\n"
            "    # via -r smarter/requirements/in/base.in\n"
        )
        self.assertIn(expected_django, text)
        expected_fresh = (
            "fresh_package==2.0.0 \\\n"
            "    --hash=sha256:fresh-package-bdist_wheel \\\n"
            "    --hash=sha256:fresh-package-sdist\n"
            "cache-results==0.2.2 \\\n"
        )
        self.assertIn(expected_fresh, text)
        # the old hash is replaced, extras are kept, and eggs aren't hashed.
        self.assertNotIn("0000000000000000", text)
        self.assertIn("cachecontrol[filecache]==0.15.0 \\\n", text)
        self.assertNotIn("bdist_egg", text)
        # the header and options are kept.
        self.assertTrue(text.startswith("#\n# This file is autogenerated by pip-compile"))
        self.assertIn("--index-url https://pypi.org/simple\n", text)

    def test_hash_is_idempotent(self):
        self.run_main("hash")
        first = self.lockfile.read_text(encoding="utf-8")
        self.run_main("hash")
        second = self.lockfile.read_text(encoding="utf-8")
        self.assertEqual(first, second)

    def test_hash_changes_nothing_when_pypi_fails(self):
        self.lockfile.write_text(LOCKFILE + "missing==1.0\n", encoding="utf-8")
        python_lockfiles.ATTEMPTS = 1
        self.addCleanup(setattr, python_lockfiles, "ATTEMPTS", 3)
        code, _, err = self.run_main("hash")
        self.assertEqual(code, 2)
        self.assertIn("Could not read PyPI", err)
        self.assertEqual(self.lockfile.read_text(encoding="utf-8"), LOCKFILE + "missing==1.0\n")

    def test_a_new_release_fails_the_cooldown(self):
        code, _, err = self.run_main("cooldown")
        self.assertEqual(code, 1)
        self.assertIn("fresh-package==2.0.0", err)
        self.assertNotIn("django", err)
        self.assertNotIn("cachecontrol==", err)

    def test_the_projects_own_packages_are_exempt(self):
        _, _, err = self.run_main("cooldown")
        self.assertNotIn("cache-results", err)

    def test_a_shorter_cooldown_passes(self):
        code, out, _ = self.run_main("cooldown", "--days", "2")
        self.assertEqual(code, 0)
        self.assertIn("No pin of 4 in 1 lockfiles", out)

    def test_a_longer_cooldown_finds_more(self):
        code, _, err = self.run_main("cooldown", "--days", "45")
        self.assertEqual(code, 1)
        self.assertIn("cachecontrol==0.15.0", err)
        self.assertNotIn("django", err)

    def test_an_allowed_package_passes(self):
        code, _, _ = self.run_main("cooldown", "--allow", "Fresh_Package")
        self.assertEqual(code, 0)

    def test_a_release_without_wheels_or_sdist_is_an_error(self):
        release = self.pypi / "eggs-only" / "1.0" / "json"
        release.parent.mkdir(parents=True)
        egg = self.file("eggs-only", "bdist_egg", NOW)
        release.write_text(json.dumps({"urls": [egg]}), encoding="utf-8")
        self.lockfile.write_text("eggs-only==1.0\n", encoding="utf-8")
        code, _, err = self.run_main("cooldown")
        self.assertEqual(code, 2)
        self.assertIn("no wheel or sdist", err)

    def test_the_default_lockfiles(self):
        lockfiles = python_lockfiles.default_lockfiles()
        names = [lockfile.name for lockfile in lockfiles]
        self.assertIn("docker.txt", names)
        self.assertIn("local.txt", names)


if __name__ == "__main__":
    unittest.main()
